SELECT json_extract(value, '$.feature') AS feature, json_extract(value, '$.anthropic') AS anthropic, json_extract(value, '$.openai') AS openai, json_extract(value, '$.azure') AS azure FROM json_each('[{"feature": "Reasoning controls", "anthropic": "Budget/adaptive mappings with model-specific guards", "openai": "Reasoning settings mapped by selected API/model", "azure": "No normal reasoning_effort/reasoning_tokens mapping"}, {"feature": "Structured response schema", "anthropic": "Legacy output_format + beta; schema transformed", "openai": "response_format or text.format", "azure": "No normal response_schema mapping"}, {"feature": "Thinking output", "anthropic": "Typed summaries, signatures/data, replay state", "openai": "API-dependent reasoning/summary representation", "azure": "Normal output path does not expose equivalent rich reasoning"}, {"feature": "Custom tool calls", "anthropic": "Native tool_use/tool_result translation", "openai": "Function calls and outputs translated", "azure": "Native tools or model-specific tool emulation"}, {"feature": "Usage accounting", "anthropic": "Output/reasoning/cache detail where available", "openai": "Provider-reported details by API", "azure": "Prompt/completion/total; streaming usage can be absent"}, {"feature": "Provider escape hatches", "anthropic": "Model args, extra_body, headers, betas; platform gates", "openai": "Provider options and API-specific fields", "azure": "Remaining constructor args via model_extras"}]');
